const tables = new Set(ENTERPRISE_RELEASE_PHASE2_TABLES);
const owned = name => { assert.match(name, /^release_phase2_ref_[a-f0-9]{16}$/); return name; };
const sourcePin = pin => {
  if (pin === ENTERPRISE_RELEASE_PHASE2_PREDECESSOR) {
    const prior=priorMarketSources(), current=sourcePin(ENTERPRISE_RELEASE_PHASE2_SOURCE);
    assert.equal(hash(prior.current),pin.appendBaseline.sha256,'The complete542 append baseline retains its independent source pin');
    assert(current.startsWith(prior.current),'Whole551 begins with the entire source-pinned542');
    const append=current.slice(prior.current.length);
    assert.equal(Buffer.byteLength(append),pin.appendBytes); assert.equal(hash(append),pin.appendSha256);
    assert.equal(hash(prior.predecessor),pin.ancestor.sha256); assert.equal(Buffer.byteLength(prior.predecessor),pin.ancestor.bytes);
    const variant=prior.predecessor+append;
    assert.equal(Buffer.byteLength(variant),pin.bytes); assert.equal(hash(variant),pin.sha256,'Whole544 source-derived native variant is exact535 plus exact9 append');
    return variant;
  }
  const target = `${pin.revision}:${pin.file ?? 'schema.sql'}`;
  assert.equal(execFileSync('git', ['rev-parse', target], { cwd: repo, encoding: 'utf8' }).trim(), pin.blob);
  const source = execFileSync('git', ['show', target], { cwd: repo, encoding: 'utf8', maxBuffer: 8 * 1024 * 1024 });
  assert.equal(hash(source), pin.sha256, 'Complete immutable native schema source matches its independent pin');
  return source;
};


