const ENTERPRISE_DEED_SCHEMA_INVERSES=[{"current":");\nCREATE UNIQUE INDEX IF NOT EXISTS ix_street_deeds_name ON street_deeds (name_lc);\nCREATE INDEX IF NOT EXISTS ix_street_deeds_district ON street_deeds (district);\nALTER TABLE street_deeds ADD COLUMN IF NOT EXISTS building_id TEXT;\nCREATE UNIQUE INDEX IF NOT EXISTS ix_street_deeds_building ON street_deeds (building_id);\nCREATE TABLE IF NOT EXISTS street_deed_building_assignments (\n  building_id TEXT PRIMARY KEY,\n  street_name TEXT NOT NULL UNIQUE,\n  assigned_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Lifetime unique-street issuance. The singleton locks cross-account claims; burns, extraction,\n-- resale and death never decrement it. Seed upgrades from every existing identity, on-chain or not.\nCREATE TABLE IF NOT EXISTS street_deed_supply (\n","baseline":");\nCREATE UNIQUE INDEX IF NOT EXISTS ix_street_deeds_name ON street_deeds (name_lc);\nCREATE INDEX IF NOT EXISTS ix_street_deeds_district ON street_deeds (district);\n-- Lifetime unique-street issuance. The singleton locks cross-account claims; burns, extraction,\n-- resale and death never decrement it. Seed upgrades from every existing identity, on-chain or not.\nCREATE TABLE IF NOT EXISTS street_deed_supply (\n"},{"current":"  at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS ix_deed_history_acct ON street_deed_history (account_id, at DESC);\n-- Deed discovery issuance.\n-- Progress is account-level: death never refreshes the primary property reward. Investigation\n-- does not reserve a building; only the final atomic claim consumes its permanent identity.\nCREATE TABLE IF NOT EXISTS street_deed_discoveries (\n  account_id TEXT NOT NULL,\n  building_id TEXT NOT NULL,\n  steps INT NOT NULL DEFAULT 0 CHECK (steps >= 0 AND steps <= 4),\n  last_step_at TIMESTAMPTZ,\n  qualified_at TIMESTAMPTZ,\n  source TEXT NOT NULL DEFAULT 'exploration' CHECK (source IN ('exploration','quest')),\n  source_ref TEXT,\n  policy_version INT NOT NULL DEFAULT 1,\n  objective_evidence TEXT NOT NULL DEFAULT '[]',\n  PRIMARY KEY (account_id, building_id)\n);\n-- Existing unclaimed three-click progress stays at version 1 and grants no title under the\n-- investigation route. New actions explicitly write version 2 and verified objective evidence.\nALTER TABLE street_deed_discoveries ADD COLUMN IF NOT EXISTS policy_version INT NOT NULL DEFAULT 1;\nALTER TABLE street_deed_discoveries ADD COLUMN IF NOT EXISTS objective_evidence TEXT NOT NULL DEFAULT '[]';\nALTER TABLE street_deed_discoveries DROP CONSTRAINT IF EXISTS street_deed_discoveries_steps_check;\nALTER TABLE street_deed_discoveries ADD CONSTRAINT street_deed_discoveries_steps_check CHECK (steps >= 0 AND steps <= 4);\nCREATE TABLE IF NOT EXISTS street_deed_primary_claims (\n  account_id TEXT PRIMARY KEY,\n  street_name TEXT NOT NULL,\n  building_id TEXT,\n  source TEXT NOT NULL,\n  claimed_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n-- The stamp prevents later secondary buyers from being mistaken for legacy primary claimants\n-- on a subsequent boot. Existing owners and original extractors retain their existing property.\nCREATE TABLE IF NOT EXISTS street_deed_discovery_migrations (\n  id INT PRIMARY KEY CHECK (id = 1)\n);\nINSERT INTO street_deed_primary_claims (account_id,street_name,source)\n  SELECT account_id,MIN(name),'legacy' FROM street_deeds\n    WHERE account_id NOT LIKE 'onchain:%'\n      AND NOT EXISTS (SELECT 1 FROM street_deed_discovery_migrations WHERE id=1)\n    GROUP BY account_id ON CONFLICT (account_id) DO NOTHING;\nINSERT INTO street_deed_primary_claims (account_id,street_name,source)\n  SELECT extracted_by_account,MIN(name),'legacy' FROM street_deeds\n    WHERE extracted_by_account IS NOT NULL AND extracted_by_account NOT LIKE 'onchain:%'\n      AND NOT EXISTS (SELECT 1 FROM street_deed_discovery_migrations WHERE id=1)\n    GROUP BY extracted_by_account ON CONFLICT (account_id) DO NOTHING;\n-- An explicit claim event is proof even if its deed has subsequently changed ownership. Other\n-- history events do not imply primary issuance. The immutable receipt records this legacy proof.\nINSERT INTO street_deed_primary_claims (account_id,street_name,source)\n  SELECT account_id,'Legacy deed claim','legacy-history' FROM street_deed_history\n    WHERE kind='claim' AND account_id NOT LIKE 'onchain:%'\n      AND NOT EXISTS (SELECT 1 FROM street_deed_discovery_migrations WHERE id=1)\n    GROUP BY account_id ON CONFLICT (account_id) DO NOTHING;\nINSERT INTO street_deed_discovery_migrations (id) VALUES (1) ON CONFLICT (id) DO NOTHING;\n-- End deed discovery issuance.\n-- Deed RE-IMPORT: a StreetDeed NFT burned back into the game (chain.js reimportDeed). The pending store\n-- + idempotency guard (the nft_reimports twin): the burner's wallet is resolved to a deedless account\n-- and the on-chain deed re-keyed to them; if they have no linked account (or already hold a street) the\n","baseline":"  at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS ix_deed_history_acct ON street_deed_history (account_id, at DESC);\n-- Deed RE-IMPORT: a StreetDeed NFT burned back into the game (chain.js reimportDeed). The pending store\n-- + idempotency guard (the nft_reimports twin): the burner's wallet is resolved to a deedless account\n-- and the on-chain deed re-keyed to them; if they have no linked account (or already hold a street) the\n"}];
const ENTERPRISE_DEED_C2_INVERSES=[{"current":"  assigned_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Lifetime unique-street issuance. The singleton locks cross-account claims; burns, extraction,\n-- resale and death never decrement it. Seed upgrades from every existing identity, on-chain or not.\nCREATE TABLE IF NOT EXISTS street_deed_supply (\n  id INT PRIMARY KEY CHECK (id = 1),\n  issued INT NOT NULL DEFAULT 0 CHECK (issued >= 0)\n);\nINSERT INTO street_deed_supply (id, issued)\n  SELECT 1, COUNT(*) FROM street_deeds ON CONFLICT (id) DO NOTHING;\n-- Phase 2 — CONTROL + THE CORNER TAKE. The deed (owner) is permanent; CONTROL (who collects the corner\n-- take) is contestable: a rival muscles in for a window, then it lapses back to the owner. `corner_at`\n-- is the corner-take lazy clock (a small bounded cash faucet `deed:corner`); a seizure forfeits pending\n","baseline":"  assigned_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Phase 2 — CONTROL + THE CORNER TAKE. The deed (owner) is permanent; CONTROL (who collects the corner\n-- take) is contestable: a rival muscles in for a window, then it lapses back to the owner. `corner_at`\n-- is the corner-take lazy clock (a small bounded cash faucet `deed:corner`); a seizure forfeits pending\n"},{"current":"ALTER TABLE street_deeds ADD COLUMN IF NOT EXISTS ownership_since_day INT;\nALTER TABLE account_persistent ADD COLUMN IF NOT EXISTS reward_wallet_since_day INT;\n\n-- Provider-neutral Consigliere delegation. Credentials and requests never hold wallet keys.\nCREATE TABLE IF NOT EXISTS agent_gateway_connections (\n  id TEXT PRIMARY KEY,\n  account_id TEXT NOT NULL REFERENCES accounts(id),\n  provider TEXT NOT NULL,\n  label TEXT NOT NULL,\n  scopes_json TEXT NOT NULL,\n  token_hash TEXT NOT NULL UNIQUE,\n  token_version INT NOT NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  expires_at TIMESTAMPTZ NOT NULL,\n  revoked_at TIMESTAMPTZ\n);\nCREATE INDEX IF NOT EXISTS ix_agent_gateway_connections_account ON agent_gateway_connections(account_id,created_at);\nCREATE TABLE IF NOT EXISTS agent_gateway_rate_buckets (\n  account_id TEXT PRIMARY KEY REFERENCES accounts(id),\n  window_id BIGINT NOT NULL,\n  used INT NOT NULL DEFAULT 0\n);\nCREATE TABLE IF NOT EXISTS agent_gateway_requests (\n  connection_id TEXT NOT NULL REFERENCES agent_gateway_connections(id),\n  request_id TEXT NOT NULL,\n  request_hash TEXT NOT NULL,\n  capability TEXT NOT NULL,\n  action_class TEXT NOT NULL,\n  state TEXT NOT NULL DEFAULT 'started',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  completed_at TIMESTAMPTZ,\n  result_code TEXT,\n  preparation_id TEXT,\n  PRIMARY KEY (connection_id,request_id)\n);\nCREATE TABLE IF NOT EXISTS agent_gateway_preparations (\n  id TEXT PRIMARY KEY,\n  connection_id TEXT NOT NULL REFERENCES agent_gateway_connections(id),\n  account_id TEXT NOT NULL REFERENCES accounts(id),\n  request_id TEXT NOT NULL,\n  capability TEXT NOT NULL,\n  arguments_json TEXT NOT NULL,\n  preview_json TEXT NOT NULL,\n  target_json TEXT NOT NULL,\n  digest TEXT NOT NULL,\n  nonce TEXT NOT NULL,\n  state TEXT NOT NULL DEFAULT 'pending',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  expires_at TIMESTAMPTZ NOT NULL,\n  confirmed_at TIMESTAMPTZ,\n  result_json TEXT,\n  UNIQUE (connection_id,request_id)\n);\nCREATE INDEX IF NOT EXISTS ix_agent_gateway_preparations_account ON agent_gateway_preparations(account_id,created_at);\nCREATE TABLE IF NOT EXISTS agent_gateway_subscriptions (\n  id TEXT PRIMARY KEY,\n  connection_id TEXT NOT NULL REFERENCES agent_gateway_connections(id),\n  account_id TEXT NOT NULL REFERENCES accounts(id),\n  topics_json TEXT NOT NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  revoked_at TIMESTAMPTZ\n);\nCREATE INDEX IF NOT EXISTS ix_agent_gateway_subscriptions_connection ON agent_gateway_subscriptions(connection_id,created_at,id);\nCREATE INDEX IF NOT EXISTS ix_agent_gateway_notifications_cursor ON notifications(character_id,created_at,id);\nCREATE INDEX IF NOT EXISTS ix_agent_gateway_coordination_cursor ON coordination_events(occurred_at,id);\n\n-- Inventory-backed gin depots. No clock-based income or mint authority.\nCREATE TABLE IF NOT EXISTS business_depots (\n  id TEXT PRIMARY KEY,\n","baseline":"ALTER TABLE street_deeds ADD COLUMN IF NOT EXISTS ownership_since_day INT;\nALTER TABLE account_persistent ADD COLUMN IF NOT EXISTS reward_wallet_since_day INT;\n\n-- Inventory-backed gin depots. No clock-based income or mint authority.\nCREATE TABLE IF NOT EXISTS business_depots (\n  id TEXT PRIMARY KEY,\n"},{"current":" account_id TEXT NOT NULL,request_key TEXT NOT NULL,identity TEXT NOT NULL,receipt JSONB NOT NULL,\n PRIMARY KEY(account_id,request_key));\n\n-- Committed purchase receipts, independent of marketing opt-in. Delivery retries\n-- use a stable receipt ID; no email is queued without a verified address.\nCREATE TABLE IF NOT EXISTS payment_receipts (\n  id TEXT PRIMARY KEY,\n  account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,\n  email TEXT NOT NULL,\n  kind TEXT NOT NULL CHECK (kind IN ('made','wire','watch')),\n  amount NUMERIC NOT NULL CHECK (amount >= 0),\n  duration_seconds INT NOT NULL CHECK (duration_seconds > 0),\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  attempts INT NOT NULL DEFAULT 0,\n  first_attempt_at TIMESTAMPTZ,\n  abandoned_at TIMESTAMPTZ,\n  claimed_until TIMESTAMPTZ,\n  lease_id TEXT,\n  sent_at TIMESTAMPTZ\n);\nCREATE INDEX IF NOT EXISTS payment_receipts_due_idx ON payment_receipts(next_attempt_at) WHERE sent_at IS NULL;\n\n-- Customer layaway reserves actual game cash and the original seller's existing item.\nCREATE TABLE IF NOT EXISTS customer_layaways (\n id TEXT PRIMARY KEY,item_id TEXT NOT NULL REFERENCES item_instances(id),\n","baseline":" account_id TEXT NOT NULL,request_key TEXT NOT NULL,identity TEXT NOT NULL,receipt JSONB NOT NULL,\n PRIMARY KEY(account_id,request_key));\n\n-- Customer layaway reserves actual game cash and the original seller's existing item.\nCREATE TABLE IF NOT EXISTS customer_layaways (\n id TEXT PRIMARY KEY,item_id TEXT NOT NULL REFERENCES item_instances(id),\n"}];
const ENTERPRISE_DEED_PREMAIN_INVERSES=[{"current":");\nCREATE UNIQUE INDEX IF NOT EXISTS ix_street_deeds_name ON street_deeds (name_lc);\nCREATE INDEX IF NOT EXISTS ix_street_deeds_district ON street_deeds (district);\nALTER TABLE street_deeds ADD COLUMN IF NOT EXISTS building_id TEXT;\nCREATE UNIQUE INDEX IF NOT EXISTS ix_street_deeds_building ON street_deeds (building_id);\nCREATE TABLE IF NOT EXISTS street_deed_building_assignments (\n  building_id TEXT PRIMARY KEY,\n  street_name TEXT NOT NULL UNIQUE,\n  assigned_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Phase 2 — CONTROL + THE CORNER TAKE. The deed (owner) is permanent; CONTROL (who collects the corner\n-- take) is contestable: a rival muscles in for a window, then it lapses back to the owner. `corner_at`\n-- is the corner-take lazy clock (a small bounded cash faucet `deed:corner`); a seizure forfeits pending\n","baseline":");\nCREATE UNIQUE INDEX IF NOT EXISTS ix_street_deeds_name ON street_deeds (name_lc);\nCREATE INDEX IF NOT EXISTS ix_street_deeds_district ON street_deeds (district);\n-- Phase 2 — CONTROL + THE CORNER TAKE. The deed (owner) is permanent; CONTROL (who collects the corner\n-- take) is contestable: a rival muscles in for a window, then it lapses back to the owner. `corner_at`\n-- is the corner-take lazy clock (a small bounded cash faucet `deed:corner`); a seizure forfeits pending\n"},{"current":"  at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS ix_deed_history_acct ON street_deed_history (account_id, at DESC);\n-- Deed discovery issuance.\n-- Progress is account-level: death never refreshes the primary property reward. Investigation\n-- does not reserve a building; only the final atomic claim consumes its permanent identity.\nCREATE TABLE IF NOT EXISTS street_deed_discoveries (\n  account_id TEXT NOT NULL,\n  building_id TEXT NOT NULL,\n  steps INT NOT NULL DEFAULT 0 CHECK (steps >= 0 AND steps <= 4),\n  last_step_at TIMESTAMPTZ,\n  qualified_at TIMESTAMPTZ,\n  source TEXT NOT NULL DEFAULT 'exploration' CHECK (source IN ('exploration','quest')),\n  source_ref TEXT,\n  policy_version INT NOT NULL DEFAULT 1,\n  objective_evidence TEXT NOT NULL DEFAULT '[]',\n  PRIMARY KEY (account_id, building_id)\n);\n-- Existing unclaimed three-click progress stays at version 1 and grants no title under the\n-- investigation route. New actions explicitly write version 2 and verified objective evidence.\nALTER TABLE street_deed_discoveries ADD COLUMN IF NOT EXISTS policy_version INT NOT NULL DEFAULT 1;\nALTER TABLE street_deed_discoveries ADD COLUMN IF NOT EXISTS objective_evidence TEXT NOT NULL DEFAULT '[]';\nALTER TABLE street_deed_discoveries DROP CONSTRAINT IF EXISTS street_deed_discoveries_steps_check;\nALTER TABLE street_deed_discoveries ADD CONSTRAINT street_deed_discoveries_steps_check CHECK (steps >= 0 AND steps <= 4);\nCREATE TABLE IF NOT EXISTS street_deed_primary_claims (\n  account_id TEXT PRIMARY KEY,\n  street_name TEXT NOT NULL,\n  building_id TEXT,\n  source TEXT NOT NULL,\n  claimed_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n-- The stamp prevents later secondary buyers from being mistaken for legacy primary claimants\n-- on a subsequent boot. Existing owners and original extractors retain their existing property.\nCREATE TABLE IF NOT EXISTS street_deed_discovery_migrations (\n  id INT PRIMARY KEY CHECK (id = 1)\n);\nINSERT INTO street_deed_primary_claims (account_id,street_name,source)\n  SELECT account_id,MIN(name),'legacy' FROM street_deeds\n    WHERE account_id NOT LIKE 'onchain:%'\n      AND NOT EXISTS (SELECT 1 FROM street_deed_discovery_migrations WHERE id=1)\n    GROUP BY account_id ON CONFLICT (account_id) DO NOTHING;\nINSERT INTO street_deed_primary_claims (account_id,street_name,source)\n  SELECT extracted_by_account,MIN(name),'legacy' FROM street_deeds\n    WHERE extracted_by_account IS NOT NULL AND extracted_by_account NOT LIKE 'onchain:%'\n      AND NOT EXISTS (SELECT 1 FROM street_deed_discovery_migrations WHERE id=1)\n    GROUP BY extracted_by_account ON CONFLICT (account_id) DO NOTHING;\n-- An explicit claim event is proof even if its deed has subsequently changed ownership. Other\n-- history events do not imply primary issuance. The immutable receipt records this legacy proof.\nINSERT INTO street_deed_primary_claims (account_id,street_name,source)\n  SELECT account_id,'Legacy deed claim','legacy-history' FROM street_deed_history\n    WHERE kind='claim' AND account_id NOT LIKE 'onchain:%'\n      AND NOT EXISTS (SELECT 1 FROM street_deed_discovery_migrations WHERE id=1)\n    GROUP BY account_id ON CONFLICT (account_id) DO NOTHING;\nINSERT INTO street_deed_discovery_migrations (id) VALUES (1) ON CONFLICT (id) DO NOTHING;\n-- End deed discovery issuance.\n-- Deed RE-IMPORT: a StreetDeed NFT burned back into the game (chain.js reimportDeed). The pending store\n-- + idempotency guard (the nft_reimports twin): the burner's wallet is resolved to a deedless account\n-- and the on-chain deed re-keyed to them; if they have no linked account (or already hold a street) the\n","baseline":"  at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS ix_deed_history_acct ON street_deed_history (account_id, at DESC);\n-- Deed RE-IMPORT: a StreetDeed NFT burned back into the game (chain.js reimportDeed). The pending store\n-- + idempotency guard (the nft_reimports twin): the burner's wallet is resolved to a deedless account\n-- and the on-chain deed re-keyed to them; if they have no linked account (or already hold a street) the\n"}];
const ENTERPRISE_DEED_PROTECTED={"enterprise-release-phase2-migration-catalog.js":"fc35f2b8770f3c7bd77347478c55eb944935fed019d40a43b101c70e5bc82570","market-operations-release-phase2-migration-catalog.js":"689d63b4273296c247fb130566a96d9c1beb049c8b0bde3169b988f66074acf1","deed-discovery-migration-catalog.js":"bd2da4747ab5a7fa41fe5630bb352e385184f73ecdadc716738b2532a845fd44","deed-quest-source-transfer.js":"05bc98b2f26de7172675b0fb17d865ffa75d299a113807f4a5160beeb8fcfe9e","deed-market-source-compatibility.js":"11c3683f55b6b960135c3d522c759f10e4e16b65b993546dc93dce899762dc26"};
const deedFields=['relations','columns','constraints','indexes'];
const deedUniform=input=>{assert.equal(typeof input,'string');const lf=input.replaceAll('\r\n','\n');assert(!lf.includes('\r')&&(input===lf||input===lf.replaceAll('\n','\r\n')),'Only whole LF or uniformCRLF source');return lf;};
const deedUndo=(source,inverses)=>{let prior=source;for(const h of inverses){assert.equal(prior.split(h.current).length-1,1,'Unique exact current Deed native inverse');prior=prior.replace(h.current,()=>h.baseline);}return prior;};
function assertEnterpriseDeedProtectedSources(){for(const[file,pin]of Object.entries(ENTERPRISE_DEED_PROTECTED)){const text=deedUniform(fs.readFileSync(new URL('./'+file,import.meta.url),'utf8'));assert.equal(hash(deedQuestSourceBaseline(file,text)),pin,'Whole protected original native/source module: '+file);}}
export function enterpriseCurrentDeedSources(input){
 assertEnterpriseDeedProtectedSources();const current=sourcePin(ENTERPRISE_DEED_CURRENT_SOURCE);assert.equal(Buffer.byteLength(current),ENTERPRISE_DEED_CURRENT_SOURCE.bytes);const normalized=deedUniform(input);assert.equal(normalized,current,'Only actual61bfb whole555 source');assert.equal([...current.matchAll(/^CREATE TABLE IF NOT EXISTS /gm)].length,555);
 const predecessor=deedUndo(current,ENTERPRISE_DEED_SCHEMA_INVERSES),old=enterpriseMigrationSources();assert.equal(predecessor,old.current,'Whole555 projects only the exact Deed delta to independently pinned551');
 return Object.freeze({current,predecessor,predecessorRevision:ENTERPRISE_RELEASE_PHASE2_SOURCE.revision});
}
export function enterpriseCurrentDeedNativeSources(){
 const source=sourcePin(ENTERPRISE_DEED_CURRENT_SOURCE),current=enterpriseCurrentDeedSources(source),premain=deedUndo(source,ENTERPRISE_DEED_C2_INVERSES),old=enterpriseMigrationSources();
 assert.equal(ENTERPRISE_DEED_C2_INVERSES.length,3);assert.equal(hash(premain),ENTERPRISE_DEED_PREMAIN_SOURCE.sha256);assert.equal(Buffer.byteLength(premain),ENTERPRISE_DEED_PREMAIN_SOURCE.bytes);assert.equal([...premain.matchAll(/^CREATE TABLE IF NOT EXISTS /gm)].length,548);
 assert.equal(deedUndo(premain,ENTERPRISE_DEED_PREMAIN_INVERSES),old.predecessor,'Whole548 projects only exact Deed delta to independently pinned544');
 return Object.freeze({current:current.current,premain,predecessor:current.predecessor,premainPredecessor:old.predecessor});
}
function enterpriseDeedSourcePair(input){const sources=enterpriseCurrentDeedNativeSources(),text=deedUniform(input);if(text===sources.current)return{current:text,predecessor:sources.predecessor,variant:'555'};assert.equal(text,sources.premain,'Only complete current555 or source-derived548');return{current:text,predecessor:sources.premainPredecessor,variant:'548'};}
async function assertEnterpriseDeedCaller(pool,endpoint,profile,includeNotNull){
 assert(['fresh','phase2','director'].includes(profile));assert.equal(typeof includeNotNull,'boolean');const address=new URL(endpoint);assert(['postgres:','postgresql:'].includes(address.protocol)&&address.hostname==='127.0.0.1'&&!address.search&&!address.hash);
 const local=['35439','35449'].includes(address.port)&&address.username==='pilot_runner'&&!address.password,ci=address.port==='5432'&&address.username==='postgres'&&address.password==='pgcheck';assert(local||ci,'Existing owned E native local/CI only');assert(['/omerta_check','/omerta_query'].includes(address.pathname)||/^\/enterprise_native_catalog_test_[a-f0-9]{12}$/.test(address.pathname));
 const settings=(await pool.query("SELECT current_schema() AS schema,current_database() AS database,current_user AS role,current_setting('server_version_num') AS version,current_setting('server_version') AS server_version,(SELECT pg_get_userbyid(nspowner) FROM pg_namespace WHERE nspname=current_schema()) AS schema_owner,(SELECT pg_get_userbyid(datdba) FROM pg_database WHERE datname=current_database()) AS database_owner")).rows[0];assert.equal(settings.role,address.username);assert.equal('/'+settings.database,address.pathname);assert.equal(settings.database_owner,settings.role);assert.match(settings.server_version,local?/^18\.4\b/:/^(?:16\b|18\.4\b)/);const version=Number(settings.version);assert(version>=160000&&version<170000||version>=180000&&version<190000);
 const main=String(process.argv[1]).replaceAll('\\','/'),focused=main.endsWith('/test/enterprise-release-phase2-migration-catalog.js')&&process.argv.length===3&&process.argv[2]==='--postgres'&&/^\/enterprise_native_catalog_test_[a-f0-9]{12}$/.test(address.pathname);
 if(focused){assert.equal(profile,'fresh');assert.equal(settings.schema,'public');}
 else {assert.equal(settings.schema_owner,settings.role);assert(['/omerta_check','/omerta_query'].includes(address.pathname));if(profile==='director'){assert(main.endsWith('/test/director-migration.js'));assert.match(settings.schema,/^director_migration_[a-f0-9]{16}$/);assert.equal(includeNotNull,false);}else{assert(main.endsWith('/test/phase2-postgres.js')&&process.argv[2]===(profile==='fresh'?'--lots':'--definitions'));assert.match(settings.schema,/^p2_definitions_[a-f0-9]{32}$/);assert.equal(process.env.P2_TEST_SCHEMA,settings.schema);assert.equal(process.env.P2_TEST_CHILD,profile==='fresh'?'lots':'upgrade');assert.equal(includeNotNull,true);}}
 return{address,version};
}
async function compileEnterpriseDeedCatalog(pool,endpoint,input,{profile,includeNotNull}){
 const sources=enterpriseDeedSourcePair(input),{address,version}=await assertEnterpriseDeedCaller(pool,endpoint,profile,includeNotNull),options={profile,serverVersionNum:version,includeNotNull};
 const compile=source=>compileReference(pool,address,source,{currentDeedHomeMigration:true});
 const baseline=freeze(await compile(sources.predecessor)),fresh=freeze(await compile(sources.current)),freshCatalog=deedDiscoveryCatalogProjection(baseline,fresh,{...options,profile:'fresh'});let catalog=freshCatalog;
 if(profile!=='fresh'){
  const legacy=enterpriseLegacySchema(profile),before=freeze(await compile(legacy+'\n'+sources.predecessor)),upgraded=freeze(await compile(legacy+'\n'+sources.current));catalog=deedDiscoveryCatalogProjection(before,upgraded,options);
  const replayed=freeze(await compile(legacy+'\n'+sources.current+'\n'+sources.current));catalog.verifyMetadata(replayed);
  const names=new Set(DEED_MIGRATION_TABLES);same(upgraded.relations.filter(r=>names.has(r.name)),fresh.relations.filter(r=>names.has(r.name)),'All fresh/upgraded Deed relations agree');for(const field of['columns','constraints','indexes'])same(upgraded[field].filter(r=>names.has(r.table_name)),fresh[field].filter(r=>names.has(r.table_name)),'All fresh/upgraded Deed '+field+' agree');
 }
 const causal=verifyDeedDiscoveryCatalogCausalNegatives(catalog,{includeNotNull});
 return Object.freeze({...catalog,predecessorSource:sources.predecessor,freshCatalog,baselineReference:baseline,freshReference:fresh,causal,source:{current:ENTERPRISE_DEED_CURRENT_SOURCE,premain:ENTERPRISE_DEED_PREMAIN_SOURCE,variant:sources.variant},phase:'current555/548 native Deed catalog only; no release or activation clearance'});
}
export async function createCurrentEnterpriseDeedNativeCatalog(pool,endpoint,input,options){const sources=enterpriseCurrentDeedSources(input),catalog=await compileEnterpriseDeedCatalog(pool,endpoint,sources.current,options);catalog.verifyMetadata(await readEnterpriseReleasePhase2Metadata(pool));return catalog;}
