 const original=await verifyHistoricalEnterpriseNativeBranches(pool,endpoint),current=await compileEnterpriseDeedCatalog(pool,endpoint,sources.current,{profile:'fresh',includeNotNull:true}),premain=await compileEnterpriseDeedCatalog(pool,endpoint,sources.premain,{profile:'fresh',includeNotNull:true});
 original.verify(current.projectMetadata(current.reference));for(const field of deedFields)same(premain.projectMetadata(premain.reference)[field],original.iv[field],'Complete548→544 old reference '+field);
